/**
 * Algebra B — recursive Cayley–Dickson (occurrence/figure 007.41).
 *
 * Defined for C = 2ⁿ only, C = 1 being the real base case. Nothing here is a
 * hard-coded Fano or octonion table: the C-dimensional product is generated by
 * the doubling below.
 *
 * Convention actually used (operand order and signs matter):
 *
 *     real base:  a·b = ab,           conj(a) = a
 *     doubling:   (a,b)·(c,d) = (ac − conj(d)·b,  d·a + b·conj(c))
 *     conjugate:  conj(a,b) = (conj(a), −b)
 *
 * with the first half of a coordinate array the "a" part. Index 0 is the real
 * unit; indices 1…C−1 span the imaginary subspace. This is the Dickson/Schafer
 * shape used by the 017.11 lane, but this module does not claim that its
 * basis labels equal any historical octonion or sedenion labeling.
 *
 * Quadratic form N(x) = Σxᵢ². The imaginary subspace is not closed under the
 * product: the scalar component of x·y is kept.
 *
 * The recursion is generic over a coefficient ring so the same code runs on
 * exact bigints and on IEEE doubles (used only for the embedding comparison).
 *
 * @module
 */
import { ObserverDomainError } from "./exact.ts";

/** Coefficient ring operations used by the doubling. */
export interface Ring<T> {
  readonly zero: T;
  add(a: T, b: T): T;
  sub(a: T, b: T): T;
  neg(a: T): T;
  mul(a: T, b: T): T;
}

/** Exact integer coefficients. */
export const BigIntRing: Ring<bigint> = {
  zero: 0n,
  add: (a, b) => a + b,
  sub: (a, b) => a - b,
  neg: (a) => -a,
  mul: (a, b) => a * b,
};

/** IEEE double coefficients; callers must keep inputs finite. */
export const NumberRing: Ring<number> = {
  zero: 0,
  add: (a, b) => a + b,
  sub: (a, b) => a - b,
  neg: (a) => -a,
  mul: (a, b) => a * b,
};

/** True when C = 2ⁿ for some n ≥ 0. */
export function cdSupported(count: number): boolean {
  return Number.isInteger(count) && count >= 1 && (count & (count - 1)) === 0;
}

/**
 * Refuses an unsupported Count with an explicit observer-domain error: no
 * rounding to a power of two, no reinterpretation as a Fano rank.
 */
export function cdAssertCount(count: number): void {
  if (count === 0) {
    throw new ObserverDomainError("Count 0 has no Cayley–Dickson algebra");
  }
  if (!cdSupported(count)) {
    throw new ObserverDomainError(
      `Count ${count} is not a power of two: no Cayley–Dickson algebra`,
    );
  }
}

/** Splits an array into its two halves. */
function halves<T>(x: readonly T[]): [T[], T[]] {
  const h = x.length / 2;
  return [x.slice(0, h), x.slice(h)];
}

/** Conjugate: real part kept, every imaginary component negated. */
export function cdConj<T>(R: Ring<T>, x: readonly T[]): T[] {
  cdAssertCount(x.length);
  if (x.length === 1) return [x[0]];
  const [a, b] = halves(x);
  return [...cdConj(R, a), ...b.map((v) => R.neg(v))];
}

function addVec<T>(R: Ring<T>, a: readonly T[], b: readonly T[]): T[] {
  return a.map((v, i) => R.add(v, b[i]));
}

function subVec<T>(R: Ring<T>, a: readonly T[], b: readonly T[]): T[] {
  return a.map((v, i) => R.sub(v, b[i]));
}

/**
 * The Cayley–Dickson product x·y of two arrays of the same power-of-two
 * length, by the doubling above.
 */
export function cdProduct<T>(
  R: Ring<T>,
  x: readonly T[],
  y: readonly T[],
): T[] {
  cdAssertCount(x.length);
  if (y.length !== x.length) {
    throw new RangeError(`length mismatch: ${x.length} vs ${y.length}`);
  }
  if (x.length === 1) return [R.mul(x[0], y[0])];
  const [a, b] = halves(x);
  const [c, d] = halves(y);
  // (a,b)(c,d) = (ac − conj(d)b, da + b conj(c))
  const first = subVec(R, cdProduct(R, a, c), cdProduct(R, cdConj(R, d), b));
  const second = addVec(R, cdProduct(R, d, a), cdProduct(R, b, cdConj(R, c)));
  return [...first, ...second];
}

/** The basis element eᵢ of dimension C. */
export function cdBasis<T>(R: Ring<T>, one: T, count: number, i: number): T[] {
  cdAssertCount(count);
  const out = new Array<T>(count).fill(R.zero);
  out[i] = one;
  return out;
}

/** Exact integer basis element. */
export function cdBasisInt(count: number, i: number): bigint[] {
  return cdBasis(BigIntRing, 1n, count, i);
}

/**
 * The left action Lₓ(y) = x·y as a C×C matrix, column j being x·eⱼ. Applying
 * it to y's coordinates is the product x·y.
 */
export function cdLeftAction<T>(
  R: Ring<T>,
  one: T,
  x: readonly T[],
): T[][] {
  const c = x.length;
  cdAssertCount(c);
  const m = Array.from({ length: c }, () => new Array<T>(c).fill(R.zero));
  for (let j = 0; j < c; j++) {
    const column = cdProduct(R, x, cdBasis(R, one, c, j));
    for (let i = 0; i < c; i++) m[i][j] = column[i];
  }
  return m;
}

/** Quadratic form N(x) = Σxᵢ². */
export function cdNormSquared<T>(R: Ring<T>, x: readonly T[]): T {
  cdAssertCount(x.length);
  return x.reduce((s, v) => R.add(s, R.mul(v, v)), R.zero);
}

/** Euclidean pairing ⟨x,y⟩ = Σxᵢyᵢ. */
export function cdInner<T>(R: Ring<T>, x: readonly T[], y: readonly T[]): T {
  return x.reduce((s, v, i) => R.add(s, R.mul(v, y[i])), R.zero);
}

/** The associator [x,y,z] = (xy)z − x(yz). */
export function cdAssociator<T>(
  R: Ring<T>,
  x: readonly T[],
  y: readonly T[],
  z: readonly T[],
): T[] {
  return subVec(
    R,
    cdProduct(R, cdProduct(R, x, y), z),
    cdProduct(R, x, cdProduct(R, y, z)),
  );
}

/** The commutator [x,y] = xy − yx. */
export function cdCommutator<T>(
  R: Ring<T>,
  x: readonly T[],
  y: readonly T[],
): T[] {
  return subVec(R, cdProduct(R, x, y), cdProduct(R, y, x));
}

/** True when every component is zero. */
export function cdIsZero(x: readonly bigint[]): boolean {
  return x.every((v) => v === 0n);
}

/**
 * Bounded deterministic search for the first basis triple (i,j,k), i,j,k ≥ 1
 * in lexicographic order, whose associator is nonzero. Returns undefined when
 * the algebra is associative on the whole basis.
 */
export function findBasisAssociatorWitness(
  count: number,
): { i: number; j: number; k: number; associator: bigint[] } | undefined {
  for (let i = 1; i < count; i++) {
    for (let j = 1; j < count; j++) {
      for (let k = 1; k < count; k++) {
        const associator = cdAssociator(
          BigIntRing,
          cdBasisInt(count, i),
          cdBasisInt(count, j),
          cdBasisInt(count, k),
        );
        if (!cdIsZero(associator)) return { i, j, k, associator };
      }
    }
  }
  return undefined;
}

/**
 * The first basis pair (i,j), 1 ≤ i < j, with eᵢeⱼ ≠ eⱼeᵢ, or undefined when
 * the algebra commutes on its basis.
 */
export function findBasisNoncommutativeWitness(
  count: number,
): { i: number; j: number; commutator: bigint[] } | undefined {
  for (let i = 1; i < count; i++) {
    for (let j = i + 1; j < count; j++) {
      const commutator = cdCommutator(
        BigIntRing,
        cdBasisInt(count, i),
        cdBasisInt(count, j),
      );
      if (!cdIsZero(commutator)) return { i, j, commutator };
    }
  }
  return undefined;
}

/** A pair of nonzero vectors with a zero product, and how it was found. */
export interface ZeroDivisorWitness {
  readonly x: bigint[];
  readonly y: bigint[];
  readonly product: bigint[];
  readonly searched: number;
}

/**
 * Bounded deterministic search for nonzero x, y with x·y = 0, where x = eₐ ± e_b
 * and y = e_c ± e_d with 1 ≤ a < b, 1 ≤ c < d < C and signs ±1 (the order is
 * a, b, sign, c, d, sign). Every candidate is counted; the first hit is
 * returned. Returns the number searched when none exists.
 */
export function findZeroDivisor(
  count: number,
): ZeroDivisorWitness | { searched: number } {
  let searched = 0;
  const vec = (p: number, q: number, s: bigint): bigint[] => {
    const v = new Array<bigint>(count).fill(0n);
    v[p] = 1n;
    v[q] = s;
    return v;
  };
  for (let a = 1; a < count; a++) {
    for (let b = a + 1; b < count; b++) {
      for (const s of [1n, -1n]) {
        const x = vec(a, b, s);
        for (let c = 1; c < count; c++) {
          for (let d = c + 1; d < count; d++) {
            for (const t of [1n, -1n]) {
              searched++;
              const y = vec(c, d, t);
              const product = cdProduct(BigIntRing, x, y);
              if (cdIsZero(product)) return { x, y, product, searched };
            }
          }
        }
      }
    }
  }
  return { searched };
}

/** A failure of N(xy) = N(x)N(y) with the values that show it. */
export interface NormCompositionWitness {
  readonly x: bigint[];
  readonly y: bigint[];
  readonly normOfProduct: bigint;
  readonly productOfNorms: bigint;
}

/**
 * First pair (x,y) from the same sparse family as `findZeroDivisor` with
 * N(xy) ≠ N(x)N(y), or undefined when every pair searched composes.
 */
export function findNormCompositionFailure(
  count: number,
): NormCompositionWitness | undefined {
  const vec = (p: number, q: number, s: bigint): bigint[] => {
    const v = new Array<bigint>(count).fill(0n);
    v[p] = 1n;
    v[q] = s;
    return v;
  };
  for (let a = 0; a < count; a++) {
    for (let b = a + 1; b < count; b++) {
      for (const s of [1n, -1n]) {
        const x = vec(a, b, s);
        for (let c = 0; c < count; c++) {
          for (let d = c + 1; d < count; d++) {
            for (const t of [1n, -1n]) {
              const y = vec(c, d, t);
              const normOfProduct = cdNormSquared(
                BigIntRing,
                cdProduct(BigIntRing, x, y),
              );
              const productOfNorms = cdNormSquared(BigIntRing, x) *
                cdNormSquared(BigIntRing, y);
              if (normOfProduct !== productOfNorms) {
                return { x, y, normOfProduct, productOfNorms };
              }
            }
          }
        }
      }
    }
  }
  return undefined;
}
